contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address spender, uint256 initial) public {
        require(spender != address(0));
        require(initial != 0);
        bool firstOk = c.approve(spender, initial); if (__ESBMC_reverted()) return;
        uint256 mid = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        bool secondOk = c.approve(spender, 0); if (__ESBMC_reverted()) return;
        uint256 afterAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        assert(firstOk && mid == initial && secondOk && afterAllowance == 0);
    }
}

